import copy

def solve_hollow_rects(grid):
    """Fill hollow rectangles based on color parity:
    - even color frame -> fill inner with 2
    - odd color frame -> fill inner with 7
    """
    h = len(grid)
    w = len(grid[0])
    result = copy.deepcopy(grid)

    # Colors that can form frames (non-background)
    frame_colors = [1, 4, 6, 8, 9]  # 3 is background

    for color in frame_colors:
        # Find all cells with this color
        cells = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    cells.append((r, c))

        if not cells:
            continue

        # Find bounding box
        r_min, r_max = min(r for r,c in cells), max(r for r,c in cells)
        c_min, c_max = min(c for r,c in cells), max(c for r,c in cells)

        # Check if it's a hollow frame (no frame-color cells strictly inside the bounding box)
        is_hollow = True
        for r in range(r_min + 1, r_max):
            for c in range(c_min + 1, c_max):
                if (r, c) in cells:
                    is_hollow = False
                    break
            if not is_hollow:
                break

        if is_hollow and r_max > r_min + 1 and c_max > c_min + 1:
            # Fill the inner region
            fill_color = 2 if color % 2 == 0 else 7
            for r in range(r_min + 1, r_max):
                for c in range(c_min + 1, c_max):
                    if grid[r][c] != color:  # Inner cell (not frame)
                        result[r][c] = fill_color

